import { BodySize } from '@walmart-web/livingdesign-components';
import { ReactNode } from 'react';
import { CommonProps } from '../../utility/commonProps';
export type InfoUnderlineVariant = 'Body' | 'Heading';
export interface IInfoUnderlineProps extends CommonProps {
    /**
     * The variant of the InfoUnderline component.
     * 'Body' or 'Heading'
     */
    variant: InfoUnderlineVariant;
    /**
     * The size of the component.
     * @default 'medium'
     */
    size?: BodySize;
    /**
     * Whether to show the underline.
     * @default true
     */
    hasUnderline?: boolean;
    /**
     * Whether to display the title text in bold.
     * @default false
     */
    bold?: boolean;
    /**
     * The title of the InfoUnderline & Popover that appears on hover/focus.
     * This text will be displayed with the underline.
     */
    title: string;
    /**
     * Optional description text for the Popover.
     */
    description?: string;
    /**
     * Optional custom content for the Popover.
     * When provided, overrides the default title/description popover.
     * Consumer is responsible for appropriate ARIA attributes
     * and semantic structure within custom content.
     * When both children and description are passed, children takes precedence.
     * The description prop is ignored for popover rendering,
     * and aria-describedby is not applied.
     */
    children?: ReactNode;
    /**
     * Maximum width of the text component. If text is longer than maxWidth, it will be truncated.
     */
    maxWidth?: number | string;
    /**
     * Controls how the popover is triggered.
     * - 'hover': popover opens on mouse enter / focus and closes on mouse leave / blur (default).
     * - 'click': popover opens/closes on click or Enter/Space; closes on Escape or outside click.
     * @default 'hover'
     */
    trigger?: 'hover' | 'click';
    /**
     * Static state for Storybook demonstration purposes.
     * When set to 'hovered' or 'focused', shows the darker underline state by default.
     * @default undefined
     */
    staticState?: 'hovered' | 'focused';
}
